      {
        "id": "composio-client-update",
        "summary": "Update @composio/client to 2.1.0 to include the latest API changes.",
        "releases": [
          {
            "name": "@composio/core",
            "type": "patch"
          }
        ]
      },
      {
        "id": "custom-toolkit-mcp-url",
        "summary": "Breaking (experimental API): `composio.experimental.customToolkits.create()` and `upsert()` take the MCP server URL as `mcpUrl` instead of `appUrl`, and send it to the API as `mcp_url`.",
        "releases": [
          {
            "name": "@composio/core",
            "type": "minor"
          },
          {
            "name": "@composio/slim",
            "type": "minor"
          }
        ]
      },
      {
        "id": "local-tools-rename",
        "summary": "Renames in-process custom tools to local tools, so they are no longer confused with the server-side custom toolkits on `composio.experimental.customToolkits`. Pass `experimental.localTools` and `experimental.localToolkits` to `composio.create()`, and `localTools` and `localToolkits` to `composio.use()`. List them with `session.localTools()` and `session.localToolkits()`. The types are now `LocalTool`, `LocalToolkit`, `RegisteredLocalTool`, `RegisteredLocalToolkit`, `CreateLocalToolParams`, `CreateLocalToolkitParams` and `LocalToolExecuteFn`. The `customTools` and `customToolkits` options, the `session.customTools()` and `session.customToolkits()` methods, and the `Custom*` type names are deprecated and keep working. Passing both a new option and its deprecated alias throws `ValidationError`. The request sent to the API is unchanged.",
        "releases": [
          {
            "name": "@composio/core",
            "type": "minor"
          },
          {
            "name": "@composio/slim",
            "type": "minor"
          }
        ]
      },
      {
        "id": "python-client-2-1-0",
        "summary": "Update `composio-client` to 2.1.0. Breaking (experimental API): `composio.experimental.custom_toolkits.create()` and `upsert()` take the MCP server URL as `mcp_url` instead of `app_url`.",
        "releases": [
          {
            "name": "@composio/python-sdk",
            "type": "minor"
          }
        ]
      },
      {
        "id": "python-local-tools-rename",
        "summary": "Renames in-process custom tools to local tools, so they are no longer confused with the server-side custom toolkits on `composio.experimental.custom_toolkits`. Pass `experimental={\"local_tools\": ..., \"local_toolkits\": ...}` to `composio.create()`, and `local_tools=` and `local_toolkits=` to `composio.use()`. List them with `session.local_tools()` and `session.local_toolkits()`. The types are now `LocalTool`, `LocalToolkit`, `RegisteredLocalTool` and `RegisteredLocalToolkit`. The `custom_tools` and `custom_toolkits` options and session methods still work but emit `ComposioDeprecationWarning`, and the `Custom*` type names remain as aliases. Passing both a new option and its deprecated alias raises `InvalidParams`. The request sent to the API is unchanged.",
        "releases": [
          {
            "name": "@composio/python-sdk",
            "type": "minor"
          }
        ]
      },
      {
        "id": "python-missing-api-key-message",
        "summary": "The error for a missing API key now explains how to set `COMPOSIO_API_KEY` or pass `api_key=`, and links to where to get a project API key, instead of suggesting `composio login`, which the Python package doesn't install.",
        "releases": [
          {
            "name": "@composio/python-sdk",
            "type": "patch"
          }
        ]
      },
      {
        "id": "python-rate-limit-handling",
        "summary": "`wait_for_connection()` handles rate limits: the delay between polls grows from 1 to 5 seconds, and a poll rejected with a 429 waits as long as its `Retry-After` header asks (up to the timeout) and polls again instead of failing the wait. A NaN timeout now times out instead of polling forever.",
        "releases": [
          {
            "name": "@composio/python-sdk",
            "type": "minor"
          }
        ]
      },
      {
        "id": "sdk-rate-limit-handling",
        "summary": "Handle rate limits better: `tools.execute()` reuses tool schemas instead of fetching one per call, `waitForConnection()` backs off between polls and waits out a 429, and tool fetches and executions rejected with a 429 throw `ComposioToolFetchRateLimitError` or `ComposioToolExecutionRateLimitError` (check with `isComposioRateLimitError`).",
        "releases": [
          {
            "name": "@composio/core",
            "type": "minor"
          }
        ]
      }
    ],
    "retainedChangesets": []
